/**
 * Marker as an effect that is affected by counterspell
 */
public class MagicMobEffect extends MobEffect implements IMobEffectEndCallback {
    public MagicMobEffect(MobEffectCategory pCategory, int pColor) {
        super(pCategory, pColor);
    }

    public MagicMobEffect(MobEffectCategory category, int color, ParticleOptions particle) {
        super(category, color, particle);
    }

    /**
     * @return VANILLA ANNOTATION: True if the effect should continue, or false if the effect should end and be removed
     */
    @Override
    public boolean applyEffectTick(LivingEntity pLivingEntity, int pAmplifier) {
        return super.applyEffectTick(pLivingEntity, pAmplifier);
    }

    /**
     * VANILLA ANNOTATION: Called when a mob effect is added or updated (ie: I have poison, I get poisoned again)
     */
    @Override
    public void onEffectStarted(LivingEntity pLivingEntity, int pAmplifier) {
        super.onEffectStarted(pLivingEntity, pAmplifier);
    }

    /**
     * VANILLA ANNOTATION: Called when a mob effect is added for the first time (ie: I did not have poison, I get poisoned)
     */
    @Override
    public void onEffectAdded(LivingEntity pLivingEntity, int pAmplifier) {
        super.onEffectAdded(pLivingEntity, pAmplifier);
    }

    @Override
    public void onEffectRemoved(LivingEntity pLivingEntity, int pAmplifier) {

    }
}

public static boolean applyDamage(Entity target, float baseAmount, DamageSource damageSource) {
    if (target instanceof LivingEntity livingTarget && damageSource instanceof SpellDamageSource spellDamageSource) {
        var e = new SpellDamageEvent(livingTarget, baseAmount, spellDamageSource);
        if (NeoForge.EVENT_BUS.post(e).isCanceled()) {
            return false;
        }
        baseAmount = e.getAmount();
        float adjustedDamage = baseAmount * getResist(livingTarget, spellDamageSource.spell.getSchoolType());
        if (damageSource.getDirectEntity() instanceof NoKnockbackProjectile) {
            ignoreNextKnockback(livingTarget);
        }
        if (damageSource.getEntity() instanceof LivingEntity livingAttacker) {
            if (isFriendlyFireBetween(livingAttacker, livingTarget)) {
                return false;
            }
            livingAttacker.setLastHurtMob(target);
        }
        return livingTarget.hurt(damageSource, adjustedDamage);
    } else {
        return target.hurt(damageSource, baseAmount);
    }
}

public static boolean isFriendlyFireBetween(@Nullable Entity attacker, @Nullable Entity target) {
    if (attacker == null || target == null) {
        return false;
    }
    if (attacker instanceof IMagicSummon summon) {
        var tmp = summon.getSummoner();
        if (tmp != null) {
            attacker = tmp;
        }
    }
    if (target instanceof IMagicSummon summon) {
        var tmp = summon.getSummoner();
        if (tmp != null) {
            target = tmp;
        }
    }
    if (attacker.isPassengerOfSameVehicle(target)) {
        return true;
    }
    if (attacker instanceof Player playerAttacker && target instanceof Player playertarget
            && !playerAttacker.canHarmPlayer(playertarget)) {
        return true;
    }
    var team = attacker.getTeam();
    if (team != null) {
        return team.isAlliedTo(target.getTeam()) && !team.isAllowFriendlyFire();
    }
    //We already manually checked for teams, so this will only return true for any overrides (such as summons)
    return attacker.isAlliedTo(target);
}

public static float getResist(LivingEntity entity, SchoolType damageSchool) {
    var baseResist = entity.getAttributeValue(AttributeRegistry.SPELL_RESIST);
    if (damageSchool == null)
        return 2 - (float) Utils.softCapFormula(baseResist);
    else
        return 2 - (float) Utils.softCapFormula(damageSchool.getResistanceFor(entity) * baseResist);
}

public void irons_spellbooks$onEffectRemoved(MobEffectInstance effectInstance, CallbackInfo ci) {
    LivingEntity self = (LivingEntity) (Object) this;
    if (!self.level.isClientSide) {
        if (effectInstance.getEffect().value() instanceof IMobEffectEndCallback mobEffect) {
            mobEffect.onEffectRemoved(self, effectInstance.getAmplifier());
        }
        if (effectInstance.getEffect().value() instanceof ISyncedMobEffect && self.level.getChunkSource() instanceof ServerChunkCache serverChunk) {
            serverChunk.broadcast(self, new ClientboundRemoveMobEffectPacket(self.getId(), effectInstance.getEffect()));
        }
    }
}

public static void onPlayerTick(PlayerTickEvent.Pre event) {
    if (event.getEntity() == Minecraft.getInstance().player) {
        var level = Minecraft.getInstance().level;

        ClientMagicData.getRecasts().tickRecasts();
        ClientMagicData.getCooldowns().tick(1);
        if (ClientMagicData.getCastDuration() > 0) {
            ClientMagicData.handleCastDuration();
        }

        if (level != null) {
            List<Entity> spellcasters = level.getEntities((Entity) null, event.getEntity().getBoundingBox().inflate(64), (mob) -> mob instanceof Player || mob instanceof IMagicEntity);
            spellcasters.forEach((entity) -> {
                LivingEntity livingEntity = (LivingEntity) entity;
                var spellData = ClientMagicData.getSyncedSpellData(livingEntity);
                /*
                Status Effect Visuals
                 */
                if (livingEntity.isAutoSpinAttack() && spellData.getSpinAttackType().equals(SpinAttackType.FIRE)) {
                    BurningDashSpell.ambientParticles(level, livingEntity);
                }
                /*
                Current Casting Spell Visuals
                 */
                //TODO: what is this, shouldnt there be an onClientCastTick?
                if (spellData.isCasting()) {
                    if (spellData.getCastingSpellId().equals(SpellRegistry.RAY_OF_SIPHONING_SPELL.get().getSpellId())) {
                        HitResult hit;
                        if (entity instanceof Mob mob && MagicData.getPlayerMagicData(mob).getAdditionalCastData() instanceof CastingMobAimingData aimingData) {
                            hit = RaycastBuilder.begin(entity.level, entity)
                                    .start(entity.getEyePosition())
                                    .end(entity.getEyePosition().add(aimingData.getForward(entity).scale(RayOfSiphoningSpell.getRange(0))))
                                    .checkForBlocks(true)
                                    .build();
                        } else {
                            hit = RaycastBuilder.begin(entity.level, entity)
                                    .range(RayOfSiphoningSpell.getRange(0))
                                    .checkForBlocks(true)
                                    .build();

                        }
                        Vec3 impact = hit.getLocation().subtract(0, .25, 0);
                        for (int i = 0; i < 8; i++) {
                            Vec3 motion = new Vec3(
                                    Utils.getRandomScaled(.2f),
                                    Utils.getRandomScaled(.2f),
                                    Utils.getRandomScaled(.2f)
                            );
                            entity.level.addParticle(ParticleHelper.SIPHON, impact.x + motion.x, impact.y + motion.y, impact.z + motion.z, motion.x, motion.y, motion.z);
                        }
                    } else if (spellData.getCastingSpellId().equals(SpellRegistry.RECALL_SPELL.get().getSpellId())) {
                        RecallSpell.ambientParticles(livingEntity, spellData);
                    } else if (spellData.getCastingSpellId().equals(SpellRegistry.RAISE_HELL_SPELL.get().getSpellId())) {
                        RaiseHellSpell.ambientParticles(livingEntity, spellData);
                    }
                }
            });
        }

    }
}

public static void onClientEntityTick(EntityTickEvent.Pre event) {
    if (event.getEntity() instanceof LivingEntity livingEntity) {
        for (MobEffectInstance inst : livingEntity.getActiveEffects()) {
            if (inst.getEffect().value() instanceof ISyncedMobEffect effect) {
                effect.clientTick(livingEntity, inst);
            }
        }
    }
}
